use glam::DVec3;
use ingetrazo_core::{mesh::Mesh,scene::Scene};
use ingetrazo_tools::fillet::fillet_edge;
fn cube()->Mesh{let mut m=Mesh::new();for p in [[0.,0.,0.],[2.,0.,0.],[2.,1.,0.],[0.,1.,0.],[0.,0.,1.],[2.,0.,1.],[2.,1.,1.],[0.,1.,1.]]{m.add_vertex(DVec3::from_array(p));}for f in [[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]]{m.add_face(f.to_vec(),vec![]).unwrap();}m}
fn save(mesh:&Mesh,path:&std::path::Path){let faces:Vec<_>=mesh.faces.iter().map(|f|serde_json::json!({"vertices":f.vertices.iter().map(|&v|mesh.vertices[v].position.to_array()).collect::<Vec<_>>(),"holes":f.holes.iter().map(|h|h.iter().map(|&v|mesh.vertices[v].position.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>()})).collect();std::fs::write(path,serde_json::to_vec(&serde_json::json!({"igz_format":1,"app_version":"independent-fixture","scene":{"edges":[],"faces":faces}})).unwrap()).unwrap();}
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());for (name,radius,segments) in [("r02-s8",0.2,8),("r01-s3",0.1,3),("r03-s16",0.3,16)]{let mut scene=Scene::new();scene.mesh=cube();let edge=scene.mesh.edges.iter().position(|e|{let a=scene.mesh.vertices[e.v0].position;let b=scene.mesh.vertices[e.v1].position;a.y==0.&&b.y==0.&&a.z==1.&&b.z==1.}).unwrap();save(&scene.mesh,&dir.join(format!("{name}-source.igz")));fillet_edge(&mut scene,edge,radius,segments).unwrap();save(&scene.mesh,&dir.join(format!("{name}-result.igz")));}}
